1	import { Queue } from 'bullmq'
2	import IORedis from 'ioredis'
3	
4	/**
5	 * BullMQ job queue enqueuer for the web service.
6	 *
7	 * The web service ONLY enqueues jobs — it never processes them.
8	 * Jobs are processed by the worker-jobs Railway service.
9	 *
10	 * Uses REDIS_PRIVATE_URL (Railway internal DNS) in production.
11	 */
12	
13	let _connection: IORedis | null = null
14	
15	function getConnection(): IORedis {
16	  if (!_connection) {
17	    const redisUrl = process.env.REDIS_PRIVATE_URL
18	    if (!redisUrl) {
19	      throw new Error('REDIS_PRIVATE_URL is not configured')
20	    }
21	    _connection = new IORedis(redisUrl, {
22	      // REQUIRED: BullMQ requires maxRetriesPerRequest to be null
23	      maxRetriesPerRequest: null,
24	      enableReadyCheck: false,
25	      lazyConnect: true,
26	    })
27	  }
28	  return _connection
29	}
30	
31	export const jobsQueue = new Queue('inkos-jobs', {
32	  connection: getConnection(),
33	  defaultJobOptions: {
34	    attempts: 3,
35	    backoff: {
36	      type: 'exponential',
37	      delay: 2000,
38	    },
39	    removeOnComplete: { count: 1000, age: 86400 },
40	    removeOnFail: { count: 5000 },
41	  },
42	})
43	
44	/**
45	 * Job payload type map — add new job types here as sprints add features.
46	 */
47	export interface JobPayloads {
48	  'send-email': {
49	    to: string
50	    template: string
51	    data: Record<string, unknown>
52	  }
53	  'generate-consent-pdf': {
54	    submissionId: string
55	    studioId: string
56	  }
57	  'process-ai-design': {
58	    requestId: string
59	    studioId: string
60	  }
61	  'send-booking-reminder': {
62	    bookingId: string
63	    reminderType: 'day_before' | 'hour_before'
64	  }
65	  'generate-payroll': {
66	    studioId: string
67	    periodStart: string
68	    periodEnd: string
69	  }
70	  'sync-calendar': {
71	    studioId: string
72	    artistId: string
73	  }
74	  'generate-1099k': {
75	    studioId: string
76	    artistId: string
77	    year: number
78	  }
79	}
80	
81	/**
82	 * Type-safe job enqueue helper.
83	 */
84	export async function enqueueJob<K extends keyof JobPayloads>(
85	  name: K,
86	  data: JobPayloads[K],
87	  options?: { delay?: number; priority?: number }
88	): Promise<string | undefined> {
89	  const job = await jobsQueue.add(name, data, options)
90	  return job.id
91	}
