import { dodo } from './client'

export interface CreateCheckoutParams {
  productId: string
  customerId?: string
  successUrl: string
  cancelUrl: string
  metadata?: Record<string, string>
  quantity?: number
}

export interface CheckoutResult {
  checkoutUrl: string
  checkoutId: string
}

/**
 * Creates a Dodo Payments checkout session and returns the redirect URL.
 * Never build a card form — always redirect to Dodo hosted checkout.
 */
export async function createCheckoutSession(params: CreateCheckoutParams): Promise<CheckoutResult> {
  const session = await dodo.subscriptions.create({
    product_id: params.productId,
    customer_id: params.customerId,
    payment_link: true,
    success_url: params.successUrl,
    cancel_url: params.cancelUrl,
    metadata: params.metadata ?? {},
    quantity: params.quantity ?? 1,
  })

  return {
    checkoutUrl: (session as { payment_link?: string; url?: string }).payment_link
      ?? (session as { payment_link?: string; url?: string }).url
      ?? '',
    checkoutId: (session as { id?: string }).id ?? '',
  }
}

/**
 * Creates a one-time payment checkout (for deposits / balance collection).
 */
export interface CreatePaymentCheckoutParams {
  productId: string
  amountCents: number
  currency: string
  customerId?: string
  customerEmail?: string
  successUrl: string
  cancelUrl: string
  metadata?: Record<string, string>
  description?: string
}

export async function createPaymentCheckout(params: CreatePaymentCheckoutParams): Promise<CheckoutResult> {
  const session = await dodo.payments.create({
    product_cart: [
      {
        product_id: params.productId,
        quantity: 1,
      },
    ],
    customer: params.customerId ? { customer_id: params.customerId } : { email: params.customerEmail ?? '' },
    payment_link: true,
    success_url: params.successUrl,
    cancel_url: params.cancelUrl,
    metadata: params.metadata ?? {},
  })

  return {
    checkoutUrl: (session as { payment_link?: string; url?: string }).payment_link
      ?? (session as { payment_link?: string; url?: string }).url
      ?? '',
    checkoutId: (session as { id?: string }).id ?? '',
  }
}

import { dodo } from './client'

/**
 * Returns the Dodo customer portal URL.
 * Owner/admin only — redirects to Dodo's hosted portal where customers manage billing.
 */
export async function getCustomerPortalUrl(customerId: string, returnUrl: string): Promise<string> {
  const portal = await dodo.customers.createCustomerPortalSession(customerId, {
    return_url: returnUrl,
  })
  return (portal as { url?: string; portal_link?: string }).url
    ?? (portal as { url?: string; portal_link?: string }).portal_link
    ?? ''
}

import { timingSafeEqual, createHmac } from 'node:crypto'
import { z } from 'zod'

// ---------------------------------------------------------------------------
// Signature verification
// ---------------------------------------------------------------------------

export async function verifyWebhookSignature(
  rawBody: string,
  signatureHeader: string | null,
  secret: string,
): Promise<boolean> {
  if (!signatureHeader) return false
  try {
    const hmac = createHmac('sha256', secret).update(rawBody).digest('hex')
    const expected = Buffer.from(hmac, 'utf-8')
    const received = Buffer.from(signatureHeader, 'utf-8')
    if (expected.length !== received.length) return false
    return timingSafeEqual(expected, received)
  } catch {
    return false
  }
}

// ---------------------------------------------------------------------------
// Shared metadata schema
// ---------------------------------------------------------------------------

const WebhookMetadataSchema = z.record(z.string()).optional()

// ---------------------------------------------------------------------------
// Per-event schemas
// ---------------------------------------------------------------------------

export const SubscriptionCreatedSchema = z.object({
  id: z.string(),
  customer_id: z.string().nullable().optional(),
  product_id: z.string().nullable().optional(),
  status: z.string(),
  billing_interval: z.string().nullable().optional(),
  current_period_start: z.string().nullable().optional(),
  current_period_end: z.string().nullable().optional(),
  trial_period_days: z.number().nullable().optional(),
  trial_start: z.string().nullable().optional(),
  trial_end: z.string().nullable().optional(),
  amount: z.number().nullable().optional(),
  currency: z.string().nullable().optional(),
  metadata: WebhookMetadataSchema,
})

export const SubscriptionUpdatedSchema = SubscriptionCreatedSchema

export const SubscriptionCancelledSchema = z.object({
  id: z.string(),
  customer_id: z.string().nullable().optional(),
  cancelled_at: z.string().nullable().optional(),
  metadata: WebhookMetadataSchema,
})

export const SubscriptionTrialEndedSchema = z.object({
  id: z.string(),
  customer_id: z.string().nullable().optional(),
  status: z.string(),
  metadata: WebhookMetadataSchema,
})

export const InvoiceSchema = z.object({
  id: z.string(),
  subscription_id: z.string().nullable().optional(),
  customer_id: z.string().nullable().optional(),
  payment_id: z.string().nullable().optional(),
  amount: z.number().nullable().optional(),
  tax: z.number().nullable().optional(),
  currency: z.string().nullable().optional(),
  status: z.string(),
  period_start: z.string().nullable().optional(),
  period_end: z.string().nullable().optional(),
  due_date: z.string().nullable().optional(),
  paid_at: z.string().nullable().optional(),
  pdf_url: z.string().nullable().optional(),
  hosted_url: z.string().nullable().optional(),
  line_items: z.array(z.unknown()).optional(),
  metadata: WebhookMetadataSchema,
})

export const PaymentSchema = z.object({
  id: z.string(),
  subscription_id: z.string().nullable().optional(),
  invoice_id: z.string().nullable().optional(),
  customer_id: z.string().nullable().optional(),
  checkout_id: z.string().nullable().optional(),
  amount: z.number(),
  currency: z.string().nullable().optional(),
  status: z.string(),
  succeeded_at: z.string().nullable().optional(),
  refund_amount: z.number().nullable().optional(),
  refunded_at: z.string().nullable().optional(),
  failure_code: z.string().nullable().optional(),
  failure_message: z.string().nullable().optional(),
  metadata: WebhookMetadataSchema,
})

export const CustomerUpdatedSchema = z.object({
  id: z.string(),
  email: z.string().nullable().optional(),
  metadata: WebhookMetadataSchema,
})

// ---------------------------------------------------------------------------
// Top-level event envelope
// ---------------------------------------------------------------------------

export const DodoWebhookEventSchema = z.discriminatedUnion('type', [
  z.object({ type: z.literal('subscription.created'),  data: SubscriptionCreatedSchema }),
  z.object({ type: z.literal('subscription.updated'),  data: SubscriptionUpdatedSchema }),
  z.object({ type: z.literal('subscription.cancelled'), data: SubscriptionCancelledSchema }),
  z.object({ type: z.literal('subscription.trial_ended'), data: SubscriptionTrialEndedSchema }),
  z.object({ type: z.literal('invoice.created'),       data: InvoiceSchema }),
  z.object({ type: z.literal('invoice.paid'),          data: InvoiceSchema }),
  z.object({ type: z.literal('invoice.payment_failed'), data: InvoiceSchema }),
  z.object({ type: z.literal('payment.succeeded'),     data: PaymentSchema }),
  z.object({ type: z.literal('payment.failed'),        data: PaymentSchema }),
  z.object({ type: z.literal('payment.refunded'),      data: PaymentSchema }),
  z.object({ type: z.literal('customer.updated'),      data: CustomerUpdatedSchema }),
])

export type DodoWebhookEvent = z.infer<typeof DodoWebhookEventSchema>

// Re-export an envelope wrapper that includes the event id used for idempotency
export const DodoEnvelopeSchema = z.object({
  event_id: z.string(),
  type: z.string(),
  created_at: z.string().optional(),
  data: z.record(z.unknown()),
})

export type DodoEnvelope = z.infer<typeof DodoEnvelopeSchema>

/**
 * Verify the raw request and return the typed event + raw envelope.
 * Throws if signature is invalid or body cannot be parsed.
 */
export async function verifyAndParse(request: Request, secret: string): Promise<{
  envelope: DodoEnvelope
  event: DodoWebhookEvent
}> {
  const rawBody = await request.text()
  const sig = request.headers.get('webhook-signature')
    ?? request.headers.get('x-dodo-signature')
    ?? null

  const valid = await verifyWebhookSignature(rawBody, sig, secret)
  if (!valid) throw new Error('invalid-signature')

  let parsed: unknown
  try {
    parsed = JSON.parse(rawBody)
  } catch {
    throw new Error('invalid-json')
  }

  const envelope = DodoEnvelopeSchema.parse(parsed)
  const event = DodoWebhookEventSchema.parse({ type: envelope.type, data: envelope.data })

  return { envelope, event }
}

/**
 * Server-side feature gating.
 *
 * Two modes:
 *  1. RPC-based (production): calls check_feature_access RPC — respects feature_flags overrides + plan features jsonb.
 *  2. Static fallback: PLAN_ORDER comparison for when RPC is unavailable (e.g. test env).
 *
 * NEVER call check_feature_access from Client Components — server-side only.
 */

import type { SupabaseClient } from '@supabase/supabase-js'

export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

const PLAN_ORDER: Record<PlanTier, number> = {
  solo: 0,
  studio: 1,
  pro: 2,
  enterprise: 3,
}

/** Minimum plan required for each feature key (static fallback) */
const FEATURE_MIN_PLAN: Record<string, PlanTier> = {
  inventory: 'studio',
  commissions: 'studio',
  payroll: 'pro',
  ai_design: 'pro',
  guest_artists: 'pro',
  eu_reach: 'pro',
  multi_location: 'pro',
  white_label: 'enterprise',
  api_access: 'enterprise',
  sms_reminders: 'studio',
  analytics: 'pro',
}

// ---------------------------------------------------------------------------
// Static helpers (no DB round-trip)
// ---------------------------------------------------------------------------

export function hasFeature(plan: PlanTier, feature: string): boolean {
  const minPlan = FEATURE_MIN_PLAN[feature]
  if (!minPlan) return true
  return PLAN_ORDER[plan] >= PLAN_ORDER[minPlan]
}

export function requiredPlanFor(feature: string): PlanTier | null {
  return FEATURE_MIN_PLAN[feature] ?? null
}

export function requireFeature(plan: PlanTier, feature: string): Response | null {
  if (hasFeature(plan, feature)) return null
  const required = FEATURE_MIN_PLAN[feature] ?? 'pro'
  return Response.json(
    { error: 'Feature not available on current plan', requiredPlan: required },
    { status: 403 },
  )
}

// ---------------------------------------------------------------------------
// Custom error for RPC-based gating
// ---------------------------------------------------------------------------

export class FeatureGateError extends Error {
  readonly featureKey: string
  constructor(featureKey: string) {
    super(`Feature '${featureKey}' is not available on current plan`)
    this.name = 'FeatureGateError'
    this.featureKey = featureKey
  }
}

// ---------------------------------------------------------------------------
// RPC-based gating (server components + API routes)
// ---------------------------------------------------------------------------

/**
 * Throws FeatureGateError if studio does not have access to featureKey.
 * Use in API routes: try { await requireFeatureRpc(...) } catch(e) { if e instanceof FeatureGateError return 403 }
 */
export async function requireFeatureRpc(
  supabase: SupabaseClient,
  studioId: string,
  featureKey: string,
): Promise<void> {
  const { data: hasAccess, error } = await supabase.rpc('check_feature_access', {
    p_studio_id: studioId,
    p_feature_key: featureKey,
  })
  if (error || !hasAccess) {
    throw new FeatureGateError(featureKey)
  }
}

/**
 * Non-throwing variant — returns boolean.
 * Use in Server Components to conditionally render locked UI.
 */
export async function checkFeatureRpc(
  supabase: SupabaseClient,
  studioId: string,
  featureKey: string,
): Promise<boolean> {
  const { data, error } = await supabase.rpc('check_feature_access', {
    p_studio_id: studioId,
    p_feature_key: featureKey,
  })
  if (error) return false
  return Boolean(data)
}

import { Resend } from 'resend'

/**
 * Resend email client — server-side only.
 * RESEND_API_KEY must start with re_
 */
export const resend = new Resend(process.env.RESEND_API_KEY)

export const FROM_EMAIL = process.env.RESEND_FROM_EMAIL ?? 'notifications@inkos.app'
export const REPLY_TO = process.env.RESEND_REPLY_TO ?? 'support@inkos.app'

// ---------------------------------------------------------------------------
// Email templates
// ---------------------------------------------------------------------------

export type EmailTemplate =
  | 'booking_confirmation'
  | 'booking_reminder_24h'
  | 'booking_reminder_2h'
  | 'deposit_received'
  | 'session_aftercare'
  | 'invoice_paid'
  | 'payment_failed'

interface TemplateData {
  booking_confirmation: {
    clientName: string
    serviceName: string
    artistName: string
    scheduledAt: string
    studioName: string
    bookingToken: string
    depositCents: number
    priceCents: number
  }
  booking_reminder_24h: {
    clientName: string
    serviceName: string
    artistName: string
    scheduledAt: string
    studioName: string
    bookingToken: string
  }
  booking_reminder_2h: {
    clientName: string
    serviceName: string
    scheduledAt: string
    studioName: string
  }
  deposit_received: {
    clientName: string
    serviceName: string
    scheduledAt: string
    depositCents: number
    studioName: string
    bookingToken: string
  }
  session_aftercare: {
    clientName: string
    serviceName: string
    aftercareMessage: string
    studioName: string
  }
  invoice_paid: {
    studioName: string
    invoiceId: string
    amountCents: number
    currency: string
    paidAt: string
    pdfUrl: string | null
  }
  payment_failed: {
    studioName: string
    amountCents: number
    currency: string
    retryUrl: string
    failureReason: string | null
  }
}

function renderHtml(template: EmailTemplate, data: TemplateData[typeof template]): string {
  switch (template) {
    case 'booking_confirmation': {
      const d = data as TemplateData['booking_confirmation']
      return `
<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:32px 24px;">
  <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;">Booking Confirmed</h1>
  <p style="color:#666;margin-bottom:24px;">Hi ${d.clientName}, your booking with ${d.studioName} is confirmed.</p>
  <div style="border:1px solid #e5e7eb;border-radius:8px;padding:16px;margin-bottom:24px;">
    <p><strong>Service:</strong> ${d.serviceName}</p>
    <p><strong>Artist:</strong> ${d.artistName}</p>
    <p><strong>Date & Time:</strong> ${d.scheduledAt}</p>
    ${d.depositCents > 0 ? `<p><strong>Deposit due:</strong> $${(d.depositCents / 100).toFixed(2)}</p>` : ''}
  </div>
  <p style="color:#888;font-size:12px;">Ref: ${d.bookingToken.split('-')[0]?.toUpperCase()}</p>
</div>`
    }
    case 'deposit_received': {
      const d = data as TemplateData['deposit_received']
      return `
<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:32px 24px;">
  <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;">Deposit Received</h1>
  <p style="color:#666;">Hi ${d.clientName}, we received your deposit of $${(d.depositCents / 100).toFixed(2)} for ${d.serviceName} at ${d.studioName}.</p>
  <p style="margin-top:16px;color:#666;">Your appointment on ${d.scheduledAt} is confirmed.</p>
  <p style="color:#888;font-size:12px;margin-top:24px;">Ref: ${d.bookingToken.split('-')[0]?.toUpperCase()}</p>
</div>`
    }
    case 'invoice_paid': {
      const d = data as TemplateData['invoice_paid']
      return `
<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:32px 24px;">
  <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;">Invoice Paid</h1>
  <p style="color:#666;">Invoice #${d.invoiceId} for $${(d.amountCents / 100).toFixed(2)} ${d.currency.toUpperCase()} has been paid on ${d.paidAt}.</p>
  ${d.pdfUrl ? `<p><a href="${d.pdfUrl}" style="color:#7c3aed;">Download PDF</a></p>` : ''}
</div>`
    }
    case 'payment_failed': {
      const d = data as TemplateData['payment_failed']
      return `
<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:32px 24px;">
  <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;color:#dc2626;">Payment Failed</h1>
  <p style="color:#666;">A payment of $${(d.amountCents / 100).toFixed(2)} ${d.currency.toUpperCase()} for ${d.studioName} could not be processed.</p>
  ${d.failureReason ? `<p style="color:#888;">Reason: ${d.failureReason}</p>` : ''}
  <a href="${d.retryUrl}" style="display:inline-block;margin-top:16px;background:#7c3aed;color:#fff;padding:10px 20px;border-radius:6px;text-decoration:none;">Update payment method</a>
</div>`
    }
    default:
      return `<p>Email: ${template}</p>`
  }
}

function getSubject(template: EmailTemplate, data: TemplateData[typeof template]): string {
  switch (template) {
    case 'booking_confirmation': return `Booking confirmed — ${(data as TemplateData['booking_confirmation']).serviceName}`
    case 'booking_reminder_24h': return `Reminder: your appointment tomorrow`
    case 'booking_reminder_2h': return `Your appointment is in 2 hours`
    case 'deposit_received': return `Deposit received — you\'re all set`
    case 'session_aftercare': return `Aftercare instructions for your session`
    case 'invoice_paid': return `Invoice paid — ${(data as TemplateData['invoice_paid']).studioName}`
    case 'payment_failed': return `Action required: payment failed`
    default: return 'InkOS notification'
  }
}

export interface SendEmailParams<T extends EmailTemplate> {
  to: string
  template: T
  data: TemplateData[T]
}

export async function sendEmail<T extends EmailTemplate>(params: SendEmailParams<T>): Promise<{ id: string }> {
  const subject = getSubject(params.template, params.data)
  const html = renderHtml(params.template, params.data)

  const result = await resend.emails.send({
    from: FROM_EMAIL,
    replyTo: REPLY_TO,
    to: params.to,
    subject,
    html,
  })

  if (result.error) {
    throw new Error(`Resend error: ${result.error.message}`)
  }

  return { id: result.data?.id ?? '' }
}

import { createClient } from '@supabase/supabase-js'
import pino from 'pino'
import type { JobPayloads } from '../../../../lib/queue'

const log = pino({ level: process.env['LOG_LEVEL'] ?? 'info' })

/**
 * send-email job handler.
 *
 * Sends the email via Resend SDK and writes a record to client_communications.
 * Called by the BullMQ worker — never directly from web routes.
 */
export async function handleSendEmail(data: JobPayloads['send-email']): Promise<void> {
  const { Resend } = await import('resend')
  const resend = new Resend(process.env['RESEND_API_KEY'])
  const fromEmail = process.env['RESEND_FROM_EMAIL'] ?? 'notifications@inkos.app'

  // Build subject + html based on template
  const subject = buildSubject(data.template, data.data)
  const html = buildHtml(data.template, data.data)

  const result = await resend.emails.send({
    from: fromEmail,
    to: data.to,
    subject,
    html,
  })

  if (result.error) {
    throw new Error(`Resend send failed: ${result.error.message}`)
  }

  log.info({ to: data.to, template: data.template, messageId: result.data?.id }, 'email sent')

  // Write to client_communications if studioId + clientId provided
  const { studioId, clientId, bookingId } = data.data as {
    studioId?: string
    clientId?: string
    bookingId?: string
  }

  if (studioId && clientId) {
    const supabase = createClient(
      process.env['NEXT_PUBLIC_SUPABASE_URL'] ?? '',
      process.env['SUPABASE_SERVICE_ROLE_KEY'] ?? '',
      { auth: { autoRefreshToken: false, persistSession: false } }
    )

    await supabase.from('client_communications').insert({
      studio_id: studioId,
      client_id: clientId,
      booking_id: bookingId ?? null,
      channel: 'email',
      direction: 'outbound',
      template: data.template,
      subject,
      body: html,
      status: 'sent',
      sent_at: new Date().toISOString(),
      provider_message_id: result.data?.id ?? null,
    })
  }
}

function buildSubject(template: string, data: Record<string, unknown>): string {
  switch (template) {
    case 'booking_confirmation': return `Booking confirmed — ${String(data['serviceName'] ?? '')}`
    case 'booking_reminder_24h': return 'Reminder: your appointment tomorrow'
    case 'booking_reminder_2h':  return 'Your appointment is in 2 hours'
    case 'deposit_received':     return "Deposit received — you're all set"
    case 'session_aftercare':    return 'Aftercare instructions for your session'
    case 'invoice_paid':         return `Invoice paid — ${String(data['studioName'] ?? '')}`
    case 'payment_failed':       return 'Action required: payment failed'
    default:                     return 'InkOS notification'
  }
}

function buildHtml(template: string, data: Record<string, unknown>): string {
  const wrap = (body: string) =>
    `<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:32px 24px;">${body}</div>`

  switch (template) {
    case 'booking_confirmation':
      return wrap(`
        <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;">Booking Confirmed</h1>
        <p style="color:#666;">Hi ${String(data['clientName'] ?? '')}, your booking with ${String(data['studioName'] ?? '')} is confirmed.</p>
        <div style="border:1px solid #e5e7eb;border-radius:8px;padding:16px;margin:24px 0;">
          <p><strong>Service:</strong> ${String(data['serviceName'] ?? '')}</p>
          <p><strong>Artist:</strong> ${String(data['artistName'] ?? '')}</p>
          <p><strong>Date &amp; Time:</strong> ${String(data['scheduledAt'] ?? '')}</p>
        </div>
      `)
    case 'deposit_received':
      return wrap(`
        <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;">Deposit Received</h1>
        <p style="color:#666;">Hi ${String(data['clientName'] ?? '')}, we received your deposit of $${((Number(data['depositCents'] ?? 0)) / 100).toFixed(2)}.</p>
        <p>Your appointment for ${String(data['serviceName'] ?? '')} on ${String(data['scheduledAt'] ?? '')} is confirmed.</p>
      `)
    case 'invoice_paid':
      return wrap(`
        <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;">Invoice Paid</h1>
        <p>Invoice #${String(data['invoiceId'] ?? '')} for $${((Number(data['amountCents'] ?? 0)) / 100).toFixed(2)} has been paid.</p>
        ${data['pdfUrl'] ? `<p><a href="${String(data['pdfUrl'])}">Download PDF</a></p>` : ''}
      `)
    case 'payment_failed':
      return wrap(`
        <h1 style="font-size:22px;font-weight:700;margin-bottom:8px;color:#dc2626;">Payment Failed</h1>
        <p>A payment of $${((Number(data['amountCents'] ?? 0)) / 100).toFixed(2)} could not be processed.</p>
        <a href="${String(data['retryUrl'] ?? '')}" style="display:inline-block;margin-top:16px;background:#7c3aed;color:#fff;padding:10px 20px;border-radius:6px;text-decoration:none;">Update payment method</a>
      `)
    default:
      return wrap(`<p>${template} notification</p>`)
  }
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { verifyWebhookSignature, DodoWebhookEventSchema, DodoEnvelopeSchema } from '@/lib/dodo/webhook'
import { resolveProduct } from '@/lib/dodo/products'
import { enqueueJob } from '@/lib/queue'
import type { DodoWebhookEvent } from '@/lib/dodo/webhook'

export const dynamic = 'force-dynamic'

/**
 * Dodo Payments webhook handler — Sprint 4 complete implementation.
 *
 * Security order (must not be reordered):
 *  1. HMAC-SHA256 signature with timingSafeEqual
 *  2. Zod parse envelope + event
 *  3. Idempotency check via webhook_events (source + event_id UNIQUE)
 *  4. DB writes via service-role client (bypasses RLS)
 *
 * Dodo retries on non-2xx — always return 200 after recording the event row,
 * even if processing fails (we record the error on the row for debugging).
 */

export async function POST(req: NextRequest) {
  const webhookKey = process.env.DODO_PAYMENTS_WEBHOOK_KEY
  if (!webhookKey) {
    logger.error('DODO_PAYMENTS_WEBHOOK_KEY is not set')
    return NextResponse.json({ error: 'webhook not configured' }, { status: 500 })
  }

  const rawBody = await req.text()
  const signatureHeader = req.headers.get('webhook-signature')
    ?? req.headers.get('x-dodo-signature')
    ?? null

  // Step 1: Verify signature before touching anything
  const isValid = await verifyWebhookSignature(rawBody, signatureHeader, webhookKey)
  if (!isValid) {
    logger.warn({ sig: signatureHeader?.slice(0, 8) }, 'dodo webhook: invalid signature')
    return NextResponse.json({ error: 'invalid signature' }, { status: 401 })
  }

  // Step 2: Parse envelope
  let rawParsed: unknown
  try {
    rawParsed = JSON.parse(rawBody)
  } catch {
    return NextResponse.json({ error: 'invalid json' }, { status: 400 })
  }

  const envelopeResult = DodoEnvelopeSchema.safeParse(rawParsed)
  if (!envelopeResult.success) {
    logger.warn({ errs: envelopeResult.error.format() }, 'dodo webhook: bad envelope shape')
    return NextResponse.json({ error: 'invalid envelope' }, { status: 400 })
  }

  const envelope = envelopeResult.data
  const eventId = envelope.event_id

  const supabase = createServiceRoleClient()

  // Step 3: Idempotency — check before any write
  const { data: existing } = await supabase
    .from('webhook_events')
    .select('id, processed_at')
    .eq('source', 'dodo')
    .eq('event_id', eventId)
    .maybeSingle()

  if (existing?.processed_at) {
    logger.info({ eventId }, 'dodo webhook: duplicate, skipping')
    return NextResponse.json({ received: true, duplicate: true })
  }

  // Step 4: Record event row (processed_at = null until done)
  await supabase.from('webhook_events').upsert(
    {
      source: 'dodo',
      event_id: eventId,
      payload: rawParsed as Parameters<typeof supabase.from>[0] extends string ? never : typeof rawParsed,
      processed_at: null,
      created_at: new Date().toISOString(),
    },
    { onConflict: 'event_id,source' }
  )

  // Step 5: Parse typed event and process
  const eventResult = DodoWebhookEventSchema.safeParse({
    type: envelope.type,
    data: envelope.data,
  })

  if (!eventResult.success) {
    // Unknown event type — record and return 200 (don't cause Dodo to retry forever)
    logger.info({ type: envelope.type, eventId }, 'dodo webhook: unrecognized event type — ignoring')
    await supabase.from('webhook_events').update({ processed_at: new Date().toISOString() }).eq('source', 'dodo').eq('event_id', eventId)
    return NextResponse.json({ received: true, ignored: true })
  }

  const event = eventResult.data

  try {
    await processEvent(event, eventId, supabase)

    await supabase
      .from('webhook_events')
      .update({ processed_at: new Date().toISOString() })
      .eq('source', 'dodo')
      .eq('event_id', eventId)

    return NextResponse.json({ received: true })
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)
    logger.error({ err, eventId, type: event.type }, 'dodo webhook: processing failed')

    await supabase
      .from('webhook_events')
      .update({ error: errMsg })
      .eq('source', 'dodo')
      .eq('event_id', eventId)

    // Return 200 so Dodo doesn't retry (we've recorded the error — ops team investigates)
    return NextResponse.json({ received: true, error: errMsg })
  }
}

// ---------------------------------------------------------------------------
// Event processors
// ---------------------------------------------------------------------------

async function processEvent(
  event: DodoWebhookEvent,
  eventId: string,
  supabase: ReturnType<typeof createServiceRoleClient>
): Promise<void> {
  logger.info({ type: event.type, eventId }, 'dodo webhook: processing')

  switch (event.type) {
    case 'subscription.created':
    case 'subscription.updated':
      await handleSubscriptionUpsert(event.data, supabase)
      break
    case 'subscription.cancelled':
      await handleSubscriptionCancelled(event.data, supabase)
      break
    case 'subscription.trial_ended':
      await handleTrialEnded(event.data, supabase)
      break
    case 'invoice.created':
      await handleInvoiceCreated(event.data, supabase)
      break
    case 'invoice.paid':
      await handleInvoicePaid(event.data, supabase)
      break
    case 'invoice.payment_failed':
      await handleInvoicePaymentFailed(event.data, supabase)
      break
    case 'payment.succeeded':
      await handlePaymentSucceeded(event.data, supabase)
      break
    case 'payment.failed':
      await handlePaymentFailed(event.data, supabase)
      break
    case 'payment.refunded':
      await handlePaymentRefunded(event.data, supabase)
      break
    case 'customer.updated':
      await handleCustomerUpdated(event.data, supabase)
      break
  }
}

// --- subscription.created / subscription.updated ---
async function handleSubscriptionUpsert(
  data: { id: string; customer_id?: string | null; product_id?: string | null; status: string; billing_interval?: string | null; current_period_start?: string | null; current_period_end?: string | null; trial_start?: string | null; trial_end?: string | null; amount?: number | null; currency?: string | null; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const studioId = data.metadata?.['studioId']
  if (!studioId) {
    logger.warn({ subscriptionId: data.id }, 'dodo: subscription event missing studioId metadata')
    return
  }

  const resolved = resolveProduct(data.product_id ?? '')
  const planTier = resolved?.tier ?? 'solo'
  const billingCycle = resolved?.billingCycle ?? 'monthly'

  const { error } = await supabase.from('subscriptions').upsert(
    {
      studio_id: studioId,
      dodo_subscription_id: data.id,
      dodo_customer_id: data.customer_id ?? null,
      plan_tier: planTier,
      billing_cycle: billingCycle,
      status: mapSubscriptionStatus(data.status),
      trial_start: data.trial_start ?? null,
      trial_end: data.trial_end ?? null,
      current_period_start: data.current_period_start ?? null,
      current_period_end: data.current_period_end ?? null,
      price_cents: data.amount ?? 0,
      currency: data.currency ?? 'USD',
      updated_at: new Date().toISOString(),
    },
    { onConflict: 'studio_id' }
  )

  if (error) throw error

  await logAuditAction(null, 'subscription.upsert', { type: 'studio', id: studioId }, { planTier, status: data.status }, studioId)
}

// --- subscription.cancelled ---
async function handleSubscriptionCancelled(
  data: { id: string; customer_id?: string | null; cancelled_at?: string | null; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const studioId = data.metadata?.['studioId']
  if (!studioId) return

  const { error } = await supabase
    .from('subscriptions')
    .update({
      status: 'canceled',
      cancelled_at: data.cancelled_at ?? new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('dodo_subscription_id', data.id)

  if (error) throw error
  await logAuditAction(null, 'subscription.cancelled', { type: 'studio', id: studioId }, null, studioId)
}

// --- subscription.trial_ended ---
async function handleTrialEnded(
  data: { id: string; status: string; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const newStatus = data.status === 'past_due' ? 'past_due' : 'active'
  const { error } = await supabase
    .from('subscriptions')
    .update({ status: newStatus, updated_at: new Date().toISOString() })
    .eq('dodo_subscription_id', data.id)

  if (error) throw error
}

// --- invoice.created ---
async function handleInvoiceCreated(
  data: { id: string; subscription_id?: string | null; customer_id?: string | null; amount?: number | null; tax?: number | null; currency?: string | null; status: string; period_start?: string | null; period_end?: string | null; due_date?: string | null; line_items?: unknown[]; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const studioId = await resolveStudioIdFromSubscription(data.subscription_id ?? null, data.customer_id ?? null, data.metadata, supabase)
  if (!studioId) return

  await supabase.from('invoices').insert({
    studio_id: studioId,
    dodo_invoice_id: data.id,
    subscription_id: await resolveSubscriptionRowId(data.subscription_id ?? null, supabase),
    amount_cents: data.amount ?? 0,
    tax_cents: data.tax ?? 0,
    currency: data.currency ?? 'USD',
    status: 'open',
    period_start: data.period_start ?? null,
    period_end: data.period_end ?? null,
    due_date: data.due_date ?? null,
    line_items: (data.line_items as Parameters<typeof supabase.from>[0] extends string ? never : typeof data.line_items) ?? [],
    metadata: {},
  })
}

// --- invoice.paid ---
async function handleInvoicePaid(
  data: { id: string; payment_id?: string | null; paid_at?: string | null; pdf_url?: string | null; hosted_url?: string | null; subscription_id?: string | null; customer_id?: string | null; metadata?: Record<string, string> | undefined; amount?: number | null; currency?: string | null },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const { error } = await supabase
    .from('invoices')
    .update({
      status: 'paid',
      dodo_payment_id: data.payment_id ?? null,
      paid_at: data.paid_at ?? new Date().toISOString(),
      pdf_url: data.pdf_url ?? null,
      hosted_url: data.hosted_url ?? null,
      updated_at: new Date().toISOString(),
    })
    .eq('dodo_invoice_id', data.id)

  if (error) throw error

  // Send invoice_paid email (async via queue)
  const studioId = await resolveStudioIdFromSubscription(data.subscription_id ?? null, data.customer_id ?? null, data.metadata, supabase)
  if (studioId) {
    const { data: studioRow } = await supabase.from('studios').select('name').eq('id', studioId).single()
    const ownerEmail = await resolveOwnerEmail(studioId, supabase)
    if (ownerEmail) {
      try {
        await enqueueJob('send-email', {
          to: ownerEmail,
          template: 'invoice_paid',
          data: {
            studioName: studioRow?.name ?? '',
            invoiceId: data.id,
            amountCents: data.amount ?? 0,
            currency: data.currency ?? 'USD',
            paidAt: data.paid_at ?? '',
            pdfUrl: data.pdf_url ?? null,
            studioId,
          } as Record<string, unknown>,
        })
      } catch (e) {
        logger.warn({ err: e }, 'dodo webhook: failed to enqueue invoice_paid email')
      }
    }
  }
}

// --- invoice.payment_failed ---
async function handleInvoicePaymentFailed(
  data: { id: string; subscription_id?: string | null; customer_id?: string | null; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  await supabase.from('invoices').update({ status: 'open', updated_at: new Date().toISOString() }).eq('dodo_invoice_id', data.id)

  if (data.subscription_id) {
    await supabase.from('subscriptions').update({ status: 'past_due', updated_at: new Date().toISOString() }).eq('dodo_subscription_id', data.subscription_id)
  }
}

// --- payment.succeeded ---
async function handlePaymentSucceeded(
  data: { id: string; invoice_id?: string | null; customer_id?: string | null; checkout_id?: string | null; amount: number; currency?: string | null; succeeded_at?: string | null; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const studioId = data.metadata?.['studioId']
    ?? await resolveStudioIdFromCustomer(data.customer_id ?? null, supabase)
  if (!studioId) {
    logger.warn({ paymentId: data.id }, 'dodo: payment.succeeded missing studioId')
    return
  }

  const paymentType = (data.metadata?.['kind'] === 'deposit' ? 'deposit'
    : data.metadata?.['kind'] === 'balance' ? 'balance'
    : 'subscription') satisfies 'deposit' | 'balance' | 'subscription'

  // Upsert payment row (dodo_payment_id has UNIQUE constraint)
  await supabase.from('payments').upsert(
    {
      studio_id: studioId,
      dodo_payment_id: data.id,
      dodo_checkout_id: data.checkout_id ?? null,
      invoice_id: await resolveInvoiceRowId(data.invoice_id ?? null, supabase),
      type: paymentType,
      amount_cents: data.amount,
      currency: data.currency ?? 'USD',
      status: 'succeeded',
      succeeded_at: data.succeeded_at ?? new Date().toISOString(),
      metadata: data.metadata ?? {},
    },
    { onConflict: 'dodo_payment_id' }
  )

  // Deposit payment — flip booking.deposit_paid
  if (data.metadata?.['kind'] === 'deposit') {
    const bookingToken = data.metadata?.['booking_token']
    if (bookingToken) {
      const { data: booking } = await supabase.from('bookings').select('id, client_id, service_id').eq('booking_token', bookingToken).single()
      if (booking) {
        await supabase.from('bookings').update({
          deposit_paid: true,
          deposit_paid_at: data.succeeded_at ?? new Date().toISOString(),
          deposit_payment_id: data.id,
        }).eq('booking_token', bookingToken)

        // Also update payment row with booking_id
        await supabase.from('payments').update({ booking_id: booking.id, client_id: booking.client_id }).eq('dodo_payment_id', data.id)

        // Enqueue deposit confirmation email
        const { data: clientRow } = await supabase.from('clients').select('email, first_name').eq('id', booking.client_id).single()
        if (clientRow?.email) {
          const { data: serviceRow } = booking.service_id
            ? await supabase.from('services').select('name, deposit_cents').eq('id', booking.service_id).single()
            : { data: null }
          const { data: bookingFull } = await supabase.from('bookings').select('scheduled_at').eq('booking_token', bookingToken).single()
          const { data: studioRow } = await supabase.from('studios').select('name').eq('id', studioId).single()

          try {
            await enqueueJob('send-email', {
              to: clientRow.email,
              template: 'deposit_received',
              data: {
                clientName: clientRow.first_name,
                serviceName: serviceRow?.name ?? '',
                scheduledAt: bookingFull?.scheduled_at
                  ? new Date(bookingFull.scheduled_at).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
                  : '',
                depositCents: serviceRow?.deposit_cents ?? data.amount,
                studioName: studioRow?.name ?? '',
                bookingToken,
                studioId,
                clientId: booking.client_id,
                bookingId: booking.id,
              } as Record<string, unknown>,
            })
          } catch (e) {
            logger.warn({ err: e }, 'dodo webhook: failed to enqueue deposit_received email')
          }
        }
      }
    }
  }

  // Balance payment — flip booking.balance_paid
  if (data.metadata?.['kind'] === 'balance') {
    const bookingId = data.metadata?.['booking_id']
    if (bookingId) {
      await supabase.from('bookings').update({
        balance_paid: true,
        balance_paid_at: data.succeeded_at ?? new Date().toISOString(),
        balance_payment_id: data.id,
      }).eq('id', bookingId)

      await supabase.from('payments').update({ booking_id: bookingId }).eq('dodo_payment_id', data.id)
    }
  }
}

// --- payment.failed ---
async function handlePaymentFailed(
  data: { id: string; customer_id?: string | null; checkout_id?: string | null; amount: number; currency?: string | null; failure_code?: string | null; failure_message?: string | null; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const studioId = data.metadata?.['studioId']
    ?? await resolveStudioIdFromCustomer(data.customer_id ?? null, supabase)
  if (!studioId) return

  await supabase.from('payments').upsert(
    {
      studio_id: studioId,
      dodo_payment_id: data.id,
      dodo_checkout_id: data.checkout_id ?? null,
      type: 'subscription',
      amount_cents: data.amount,
      currency: data.currency ?? 'USD',
      status: 'failed',
      failure_code: data.failure_code ?? null,
      failure_message: data.failure_message ?? null,
      metadata: data.metadata ?? {},
    },
    { onConflict: 'dodo_payment_id' }
  )

  // Enqueue payment_failed email to studio owner
  const ownerEmail = await resolveOwnerEmail(studioId, supabase)
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  if (ownerEmail) {
    const { data: studioRow } = await supabase.from('studios').select('name').eq('id', studioId).single()
    try {
      await enqueueJob('send-email', {
        to: ownerEmail,
        template: 'payment_failed',
        data: {
          studioName: studioRow?.name ?? '',
          amountCents: data.amount,
          currency: data.currency ?? 'USD',
          retryUrl: `${appUrl}/settings/billing`,
          failureReason: data.failure_message ?? null,
          studioId,
        } as Record<string, unknown>,
      })
    } catch (e) {
      logger.warn({ err: e }, 'dodo webhook: failed to enqueue payment_failed email')
    }
  }
}

// --- payment.refunded ---
async function handlePaymentRefunded(
  data: { id: string; refund_amount?: number | null; refunded_at?: string | null; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  await supabase.from('payments').update({
    status: 'refunded',
    refund_amount_cents: data.refund_amount ?? 0,
    refunded_at: data.refunded_at ?? new Date().toISOString(),
    updated_at: new Date().toISOString(),
  }).eq('dodo_payment_id', data.id)

  // Update matching refund_request to processed
  await supabase.from('refund_requests').update({
    status: 'processed',
    dodo_refund_id: data.id,
    processed_at: data.refunded_at ?? new Date().toISOString(),
    updated_at: new Date().toISOString(),
  }).eq('dodo_refund_id', data.id)
}

// --- customer.updated ---
async function handleCustomerUpdated(
  data: { id: string; metadata?: Record<string, string> | undefined },
  supabase: ReturnType<typeof createServiceRoleClient>
) {
  const studioId = data.metadata?.['studioId']
  if (!studioId) return

  await supabase.from('subscriptions').update({
    dodo_customer_id: data.id,
    updated_at: new Date().toISOString(),
  }).eq('studio_id', studioId)
}

// ---------------------------------------------------------------------------
// Lookup helpers
// ---------------------------------------------------------------------------

function mapSubscriptionStatus(status: string): 'trialing' | 'active' | 'past_due' | 'canceled' | 'unpaid' {
  switch (status) {
    case 'trialing': return 'trialing'
    case 'active':   return 'active'
    case 'past_due': return 'past_due'
    case 'canceled': case 'cancelled': return 'canceled'
    case 'unpaid':   return 'unpaid'
    default:         return 'active'
  }
}

async function resolveStudioIdFromSubscription(
  dodoSubId: string | null,
  customerId: string | null,
  metadata: Record<string, string> | undefined,
  supabase: ReturnType<typeof createServiceRoleClient>
): Promise<string | null> {
  if (metadata?.['studioId']) return metadata['studioId']

  if (dodoSubId) {
    const { data } = await supabase.from('subscriptions').select('studio_id').eq('dodo_subscription_id', dodoSubId).maybeSingle()
    if (data) return data.studio_id
  }

  if (customerId) {
    return resolveStudioIdFromCustomer(customerId, supabase)
  }

  return null
}

async function resolveStudioIdFromCustomer(
  customerId: string | null,
  supabase: ReturnType<typeof createServiceRoleClient>
): Promise<string | null> {
  if (!customerId) return null
  const { data } = await supabase.from('subscriptions').select('studio_id').eq('dodo_customer_id', customerId).maybeSingle()
  return data?.studio_id ?? null
}

async function resolveSubscriptionRowId(
  dodoSubId: string | null,
  supabase: ReturnType<typeof createServiceRoleClient>
): Promise<string | null> {
  if (!dodoSubId) return null
  const { data } = await supabase.from('subscriptions').select('id').eq('dodo_subscription_id', dodoSubId).maybeSingle()
  return data?.id ?? null
}

async function resolveInvoiceRowId(
  dodoInvoiceId: string | null,
  supabase: ReturnType<typeof createServiceRoleClient>
): Promise<string | null> {
  if (!dodoInvoiceId) return null
  const { data } = await supabase.from('invoices').select('id').eq('dodo_invoice_id', dodoInvoiceId).maybeSingle()
  return data?.id ?? null
}

async function resolveOwnerEmail(
  studioId: string,
  supabase: ReturnType<typeof createServiceRoleClient>
): Promise<string | null> {
  const { data } = await supabase
    .from('studio_members')
    .select('profiles(email)')
    .eq('studio_id', studioId)
    .eq('role', 'owner')
    .limit(1)
    .maybeSingle()

  return (data?.profiles as { email?: string } | null)?.email ?? null
}

