import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { createCheckoutSession } from '@/lib/dodo/checkout'
import { getProductId } from '@/lib/dodo/products'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const BodySchema = z.object({
  tier: z.enum(['solo', 'studio', 'pro', 'enterprise']),
  billingCycle: z.enum(['monthly', 'annual']),
})

/**
 * POST /api/billing/checkout
 * Creates a Dodo Payments subscription checkout session and returns the redirect URL.
 * Never expose card forms — always redirect to Dodo hosted checkout.
 */
export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const body = BodySchema.safeParse(await req.json().catch(() => ({})))
  if (!body.success) {
    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
  }

  const { tier, billingCycle } = body.data
  const productId = getProductId(tier, billingCycle)
  if (!productId) {
    return NextResponse.json({ error: 'product not configured for this tier' }, { status: 400 })
  }

  const supabase = await createClient()

  // Get existing Dodo customer ID if studio already subscribed
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('dodo_customer_id')
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''

  try {
    const result = await createCheckoutSession({
      productId,
      customerId: sub?.dodo_customer_id ?? undefined,
      successUrl: `${appUrl}/settings/billing?success=1`,
      cancelUrl: `${appUrl}/settings/billing?cancelled=1`,
      metadata: {
        studioId: auth.studioId,
        userId: auth.user.authId,
        tier,
        billingCycle,
      },
    })

    await logAuditAction(
      auth.user.authId,
      'billing.checkout.created',
      { type: 'studio', id: auth.studioId },
      { tier, billingCycle, checkoutId: result.checkoutId },
      auth.studioId,
    )

    return NextResponse.json({ checkoutUrl: result.checkoutUrl, checkoutId: result.checkoutId })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId, tier }, 'billing checkout creation failed')
    return NextResponse.json({ error: 'failed to create checkout session' }, { status: 500 })
  }
}

