import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { dodo } from '@/lib/dodo/client'

export const dynamic = 'force-dynamic'

/**
 * POST /api/billing/cancel
 * Sets cancel_at_period_end = true on the subscription.
 * Owner role required. Does NOT cancel immediately.
 */
export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner') {
    return NextResponse.json({ error: 'owner role required' }, { status: 403 })
  }

  const supabase = await createClient()
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('id, dodo_subscription_id, status')
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!sub?.dodo_subscription_id) {
    return NextResponse.json({ error: 'no active subscription found' }, { status: 404 })
  }

  if (sub.status === 'canceled') {
    return NextResponse.json({ error: 'subscription is already cancelled' }, { status: 409 })
  }

  try {
    // Cancel at period end via Dodo API
    await (dodo.subscriptions as unknown as { update: (id: string, params: Record<string, unknown>) => Promise<unknown> }).update(sub.dodo_subscription_id, {
      cancel_at_period_end: true,
    })

    // Optimistically update local state (webhook will confirm)
    await supabase
      .from('subscriptions')
      .update({ cancel_at_period_end: true, updated_at: new Date().toISOString() })
      .eq('id', sub.id)

    await logAuditAction(
      auth.user.authId,
      'billing.subscription.cancel_requested',
      { type: 'studio', id: auth.studioId },
      { dodoSubscriptionId: sub.dodo_subscription_id },
      auth.studioId,
    )

    return NextResponse.json({ ok: true })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'subscription cancel failed')
    return NextResponse.json({ error: 'failed to cancel subscription' }, { status: 500 })
  }
}

