import { dodo } from '@/lib/dodo/client'

export const dynamic = 'force-dynamic'

/**
 * POST /api/billing/resume
 * Undoes cancel_at_period_end — resumes the subscription.
 * Owner role required.
 */
export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner') {
    return NextResponse.json({ error: 'owner role required' }, { status: 403 })
  }

  const supabase = await createClient()
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('id, dodo_subscription_id, cancel_at_period_end')
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!sub?.dodo_subscription_id) {
    return NextResponse.json({ error: 'no subscription found' }, { status: 404 })
  }

  if (!sub.cancel_at_period_end) {
    return NextResponse.json({ error: 'subscription is not scheduled for cancellation' }, { status: 409 })
