import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { createPaymentCheckout } from '@/lib/dodo/checkout'

export const dynamic = 'force-dynamic'

/**
 * POST /api/bookings/[id]/collect-balance
 * Creates a Dodo one-time payment checkout for the booking balance (total - deposit).
 * Returns a checkoutUrl to redirect the client.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const { id: bookingId } = await params

  const supabase = await createClient()

  const { data: booking } = await supabase
    .from('bookings')
    .select(`
      id, booking_token, studio_id, client_id,
      deposit_paid, balance_paid, balance_paid_at,
      services(id, name, price_cents, deposit_cents),
      clients(id, email, first_name, last_name)
    `)
    .eq('id', bookingId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!booking) {
    return NextResponse.json({ error: 'booking not found' }, { status: 404 })
  }

  if (booking.balance_paid) {
    return NextResponse.json({ error: 'balance already collected' }, { status: 409 })
  }

  const service = booking.services as { id: string; name: string; price_cents: number; deposit_cents: number } | null
  if (!service) {
    return NextResponse.json({ error: 'service details not found' }, { status: 400 })
  }

  const balanceCents = service.price_cents - service.deposit_cents
  if (balanceCents <= 0) {
    return NextResponse.json({ error: 'no balance outstanding' }, { status: 400 })
  }

  const client = booking.clients as { id: string; email: string; first_name: string; last_name: string } | null
  const clientEmail = client?.email ?? ''

  // Get subscription for Dodo customer ID
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('dodo_customer_id')
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  // Get balance product ID from env (one-time product for balance collection)
  const balanceProductId = process.env.DODO_PRODUCT_BALANCE_COLLECTION ?? ''
  if (!balanceProductId) {
    return NextResponse.json({ error: 'balance collection product not configured' }, { status: 500 })
  }

  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''

  try {
    const result = await createPaymentCheckout({
      productId: balanceProductId,
      amountCents: balanceCents,
      currency: 'USD',
      customerId: sub?.dodo_customer_id ?? undefined,
      customerEmail: clientEmail,
      successUrl: `${appUrl}/appointments/${bookingId}?balance_paid=1`,
      cancelUrl: `${appUrl}/appointments/${bookingId}`,
      metadata: {
        kind: 'balance',
        booking_id: bookingId,
        studioId: auth.studioId,
        clientId: booking.client_id,
      },
      description: `Balance for ${service.name}`,
    })

    await logAuditAction(
      auth.user.authId,
      'booking.balance.checkout_created',
      { type: 'booking', id: bookingId },
      { balanceCents, checkoutId: result.checkoutId },
      auth.studioId,
    )

    return NextResponse.json({ checkoutUrl: result.checkoutUrl, checkoutId: result.checkoutId })
  } catch (err) {
    logger.error({ err, bookingId, studioId: auth.studioId }, 'balance checkout creation failed')
    return NextResponse.json({ error: 'failed to create balance checkout' }, { status: 500 })
  }
}

import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const BodySchema = z.object({
  reason: z.enum(['client_request', 'error', 'duplicate', 'other']).optional().default('client_request'),
  notes: z.string().max(500).optional(),
})

/**
 * POST /api/bookings/[id]/refund-deposit
 * Creates a refund_requests row for the booking's deposit payment.
 * The actual Dodo refund is processed by the admin after review.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'insufficient permissions' }, { status: 403 })
  }

  const { id: bookingId } = await params

  const body = BodySchema.safeParse(await req.json().catch(() => ({})))
  if (!body.success) {
    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  const { data: booking } = await supabase
    .from('bookings')
    .select('id, studio_id, deposit_paid, deposit_payment_id, services(deposit_cents)')
    .eq('id', bookingId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!booking) {
    return NextResponse.json({ error: 'booking not found' }, { status: 404 })
  }

  if (!booking.deposit_paid) {
    return NextResponse.json({ error: 'no deposit has been collected for this booking' }, { status: 409 })
  }

  if (!booking.deposit_payment_id) {
    return NextResponse.json({ error: 'deposit payment ID not found — contact support' }, { status: 400 })
  }

  // Get the payment row
  const { data: payment } = await supabase
    .from('payments')
    .select('id, dodo_payment_id, amount_cents, status')
    .eq('dodo_payment_id', booking.deposit_payment_id)
    .maybeSingle()

  if (!payment) {
    return NextResponse.json({ error: 'payment record not found' }, { status: 404 })
  }

  if (payment.status === 'refunded') {
    return NextResponse.json({ error: 'deposit has already been refunded' }, { status: 409 })
  }

  // Check for existing pending refund request
  const { data: existingRequest } = await supabase
    .from('refund_requests')
    .select('id, status')
    .eq('payment_id', payment.id)
    .maybeSingle()

  if (existingRequest && existingRequest.status !== 'rejected') {
    return NextResponse.json({ error: 'refund request already exists for this deposit', refundRequestId: existingRequest.id }, { status: 409 })
  }

  const service = booking.services as { deposit_cents: number } | null
  const depositCents = service?.deposit_cents ?? payment.amount_cents

  const { data: refundReq, error } = await supabase
    .from('refund_requests')
    .insert({
      studio_id: auth.studioId,
      payment_id: payment.id,
      dodo_payment_id: payment.dodo_payment_id,
      amount_cents: depositCents,
      reason: body.data.reason,
      notes: body.data.notes ?? null,
      status: 'pending',
      requested_by: auth.user.authId,
    })
    .select()
    .single()

  if (error) {
    logger.error({ err: error, bookingId, studioId: auth.studioId }, 'deposit refund request insert failed')
    return NextResponse.json({ error: 'failed to create refund request' }, { status: 500 })
  }

  await logAuditAction(
    auth.user.authId,
    'booking.deposit.refund_requested',
    { type: 'booking', id: bookingId },
    { depositCents, reason: body.data.reason },
    auth.studioId,
  )

  return NextResponse.json({ refundRequest: refundReq }, { status: 201 })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'

export const dynamic = 'force-dynamic'

/**
 * GET /api/feature-access/[key]
 * Runtime feature gate check using check_feature_access RPC.
 * Returns { hasAccess: boolean }
 *
 * Prefer server-side gating (requireFeatureRpc) in API routes.
 * This endpoint exists for client components that need to conditionally render.
 */
export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ key: string }> }
) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const { key } = await params
  if (!key || key.length > 64) {
    return NextResponse.json({ error: 'invalid feature key' }, { status: 400 })
  }

  const supabase = await createClient()

  const { data: hasAccess, error } = await supabase.rpc('check_feature_access', {
    p_studio_id: auth.studioId,
    p_feature_key: key,
  })

  if (error) {
    return NextResponse.json({ hasAccess: false })
  }

  return NextResponse.json({ hasAccess: Boolean(hasAccess) })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/billing/overview
 * Platform-admin only. Returns MRR, active subscriptions, trials, churn data.
 */
export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (!auth.user.is_platform_admin) return NextResponse.json({ error: 'forbidden' }, { status: 403 })

  const supabase = await createClient()

  const [activeResult, trialResult, pastDueResult, cancelledResult, mrrResult] = await Promise.all([
    supabase.from('subscriptions').select('id', { count: 'exact', head: true }).eq('status', 'active'),
    supabase.from('subscriptions').select('id', { count: 'exact', head: true }).eq('status', 'trialing'),
    supabase.from('subscriptions').select('id', { count: 'exact', head: true }).eq('status', 'past_due'),
    supabase
      .from('subscriptions')
      .select('id', { count: 'exact', head: true })
      .eq('status', 'canceled')
      .gte('cancelled_at', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString()),
    supabase
      .from('subscriptions')
      .select('price_cents, billing_cycle')
      .in('status', ['active', 'trialing']),
  ])

  if (mrrResult.error) {
    logger.error({ err: mrrResult.error }, 'admin billing overview: mrr query failed')
    return NextResponse.json({ error: 'failed to load billing overview' }, { status: 500 })
  }

  // Compute MRR (convert annual to monthly)
  const mrr = (mrrResult.data ?? []).reduce((sum, sub) => {
    const monthly = sub.billing_cycle === 'annual' ? sub.price_cents / 12 : sub.price_cents
    return sum + monthly
  }, 0)

  // Per-plan breakdown
  const planBreakdown = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .in('status', ['active', 'trialing'])

  const tierCounts: Record<string, number> = {}
  for (const sub of planBreakdown.data ?? []) {
    tierCounts[sub.plan_tier] = (tierCounts[sub.plan_tier] ?? 0) + 1
  }

  return NextResponse.json({
    activeCount: activeResult.count ?? 0,
    trialCount: trialResult.count ?? 0,
    pastDueCount: pastDueResult.count ?? 0,
    cancelledLast30dCount: cancelledResult.count ?? 0,
    mrrCents: Math.round(mrr),
    planBreakdown: tierCounts,
  })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/billing/subscriptions?page=1&limit=25&status=active&search=
 * Platform-admin only. Lists all subscriptions with studio info.
 */
export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (!auth.user.is_platform_admin) return NextResponse.json({ error: 'forbidden' }, { status: 403 })

  const { searchParams } = new URL(req.url)
  const page = Math.max(1, Number(searchParams.get('page') ?? '1'))
  const limit = Math.min(100, Math.max(1, Number(searchParams.get('limit') ?? '25')))
  const status = searchParams.get('status')
  const offset = (page - 1) * limit

  const supabase = await createClient()

  let query = supabase
    .from('subscriptions')
    .select(
      `id, studio_id, plan_tier, billing_cycle, status, price_cents, currency,
       trial_start, trial_end, current_period_end, cancel_at_period_end, cancelled_at,
       dodo_subscription_id, dodo_customer_id, created_at, updated_at,
       studios(id, name, slug)`,
      { count: 'exact' }
    )
    .order('created_at', { ascending: false })
    .range(offset, offset + limit - 1)

  if (status) {
    query = query.eq('status', status)
  }

  const { data, error, count } = await query

  if (error) {
    logger.error({ err: error }, 'admin subscriptions fetch failed')
    return NextResponse.json({ error: 'failed to load subscriptions' }, { status: 500 })
  }

  return NextResponse.json({
    subscriptions: data ?? [],
    total: count ?? 0,
    page,
    limit,
    hasMore: ((count ?? 0) > offset + limit),
  })
}
